// Starter documents for new pages. Every section demonstrates one supported element with
// clearly replaceable example copy ("This Is a Card"…). Text marked data-cms-bind comes from
// Details (title, summary, price, dates…); data-cms-component blocks are generated by the
// website. Styles come from css/style.css; Page CSS starts with a short example.
//
// Images point at the site's placeholder artwork (assets/images/placeholder-*.svg), clearly
// labelled as placeholders. Video sections stay empty until a YouTube or Vimeo address is
// added in the visual editor, so nothing pretends to play.

import { TESTIMONIAL_CARD } from "./page-doc.mjs";
// Page CSS holds only what is special to one page; the site styles (css/style.css) do the rest.
const CSS = `/* Styles for this page only (the website styles already apply).
   Add your own classes here, for example:

.my-highlight {
  background: var(--yellow-pastel);
  border-radius: var(--r);
  padding: 24px;
}
*/
`;


const card = (title, text, tone = "") => `      <article class="fw-card${tone ? ` fw-card--${tone}` : ""}">
        <p class="fw-card__label">Example card</p>
        <h3>${title}</h3>
        <p>${text}</p>
      </article>`;

const VIDEO = `<section class="section wrap fw-section" aria-labelledby="video-title">
  <div class="fw-section__head">
    <h2 id="video-title">This Is a Video</h2>
    <p>Select the video block and paste a YouTube or Vimeo address in the panel. Until then, the block shows a placeholder and nothing plays.</p>
  </div>
  <figure class="fw-video">
    <div class="fw-video__empty">Video placeholder · add a YouTube or Vimeo address in the editor</div>
    <figcaption>Optional caption for the video.</figcaption>
  </figure>
</section>`;

const IMAGE = (alt) => `<section class="section wrap fw-section fw-split" aria-labelledby="image-title">
  <figure class="fw-media">
    <img src="/assets/images/placeholder-4x3.svg" alt="${alt}" width="1200" height="900" loading="lazy">
    <figcaption>Replace this placeholder: select the image and change its address and description.</figcaption>
  </figure>
  <div>
    <h2 id="image-title">This Is an Image</h2>
    <p>Images sit beside text on wide screens and stack on phones. Always describe what the image shows (alt text) for people using screen readers.</p>
    <a class="text-link" href="/about/">This Is a Text Link <span class="link-arrow" aria-hidden="true">↗</span></a>
  </div>
</section>`;

const QUOTE = `<section class="section wrap fw-section" aria-labelledby="quote-title">
  <div class="fw-section__head"><h2 id="quote-title">This Is a Testimonial</h2><p>Example layout only. Use a real quote, word for word, with the person’s recorded consent, or delete this section.</p></div>
  <div class="quotes fw-quotes">
    <figure class="quote quote--pink">
      <blockquote><p>Example quote. Replace it with the participant’s exact words.</p></blockquote>
      <figcaption>Participant name<span>Role or organization</span></figcaption>
    </figure>
  </div>
</section>`;

const FAQ = (q1, a1) => `<section class="section section--rule wrap" aria-labelledby="faq-title">
  <div class="faq">
    <div class="faq__head"><h2 id="faq-title">This Is an FAQ</h2></div>
    <div class="faq__items">
      <details><summary>${q1}</summary><p>${a1}</p></details>
      <details><summary>Can I add more questions?</summary><p>Yes. Select a question and use Duplicate, then edit the copy.</p></details>
      <details><summary>Can I remove this section?</summary><p>Yes. Select the section (use “Select parent” to reach it) and delete it.</p></details>
    </div>
  </div>
</section>`;

const CONTACT = `<section class="section wrap fw-section" aria-labelledby="contact-title">
  <div class="fw-contact">
    <div>
      <h2 id="contact-title" class="h3">Questions before you join?</h2>
      <p>This is a contact section. Point the button at the Contact page or a specific inquiry.</p>
    </div>
    <a class="btn btn--light" href="/contact/">Contact Faith Works</a>
  </div>
</section>`;

function programs() {
  return `<!--
  THIS IS JUST A TEMPLATE. Every section below is an example: change it, delete it, or replace it
  with your own HTML, classes and Page CSS. Add sections the program needs (schedule, pricing tiers, mentors…).
  Keep the elements marked data-cms-… if you want them to follow Details (title, summary, price, dates…).
  This note is not published.
-->
<section class="phero phero--pink phero--program" aria-labelledby="page-title">
  <div class="wrap phero__grid">
    <div class="phero__copy">
      <nav class="crumbs" aria-label="Breadcrumb"><a href="/learn/">Learn AI</a><span aria-hidden="true">/</span><span aria-current="page">Program</span></nav>
      <h1 id="page-title" data-cms-bind="title">This Is the Full HTML Template</h1>
      <p class="phero__lead" data-cms-bind="summary">This section demonstrates a heading and introductory paragraph.</p>
      <div class="actions">
        <a class="btn" href="#register">This Is a Call to Action <span class="btn__arrow btn__arrow--down" aria-hidden="true">↓</span></a>
        <a class="btn btn--light" href="/contact/?type=programs">Ask a question</a>
      </div>
    </div>
    <aside class="facts" aria-label="Program facts">
      <dl>
        <div><dt>Status</dt><dd data-cms-component="status-badge"></dd></div>
        <div><dt>Format</dt><dd data-cms-extract="format">Example: four live online sessions</dd></div>
        <div><dt>Time commitment</dt><dd>Example: 2 hours a week for 4 weeks</dd></div>
        <div><dt>Fee</dt><dd data-cms-bind="price" data-cms-empty="Published when the next intake is confirmed"></dd></div>
        <div><dt>Next intake</dt><dd><span class="tbc">To be announced</span></dd></div>
      </dl>
    </aside>
  </div>
</section>

<div class="article__cover wrap" data-cms-component="featured-image"></div>

<section class="section wrap fw-section" aria-labelledby="cards-title">
  <div class="fw-section__head">
    <h2 id="cards-title">This Is a Card</h2>
    <p>Cards group short points. Use two, three or four per row; they stack on phones.</p>
  </div>
  <div class="fw-grid fw-grid--3">
${card("Who it’s for", "Describe the people this program serves and the problem it solves for them.")}
${card("What you’ll do", "Explain the main activity in one or two sentences.", "pink")}
${card("What you’ll leave with", "Name the concrete result participants take home.", "yellow")}
  </div>
</section>

<section class="section band band--stone" aria-labelledby="list-title">
  <div class="wrap fw-split">
    <div>
      <h2 id="list-title">This Is a List</h2>
      <p>Lists with ticks are good for audiences, outcomes and requirements. The lists marked for cards also appear on the Learn page.</p>
      <h3 class="fw-subhead">Who it’s for</h3>
      <ul class="ticks" data-cms-list="audience">
        <li>Example audience: professionals new to AI</li>
        <li>Example audience: founders and small business owners</li>
      </ul>
    </div>
    <div class="fw-panel">
      <h3 class="fw-subhead">What you leave with</h3>
      <ul class="ticks" data-cms-list="outputs">
        <li>Example output: a documented workflow</li>
        <li>Example output: a first working prototype</li>
      </ul>
      <h3 class="fw-subhead">What you need</h3>
      <ul class="ticks" data-cms-list="requirements">
        <li>A laptop and internet connection</li>
        <li>One recurring task from your own work</li>
      </ul>
    </div>
  </div>
</section>

${IMAGE("Placeholder image: replace with a photo from a Faith Works session")}

${VIDEO}

<section class="section wrap fw-section" aria-labelledby="agenda-title">
  <div class="section-head"><h2 id="agenda-title">This Is a Numbered Outline</h2><p>The planned flow of the program, step by step.</p></div>
  <ol class="agenda">
    <li><h3>Step one</h3><p>What happens first.</p></li>
    <li><h3>Step two</h3><p>What happens next.</p></li>
    <li><h3>Step three</h3><p>How participants finish.</p></li>
  </ol>
</section>

${QUOTE}

${FAQ("Do I need a technical background?", "Example answer. Replace it with the approved answer for this program.")}

<section class="section band band--pink" id="register" aria-labelledby="register-title">
  <div class="wrap formblock">
    <div class="formblock__intro">
      <h2 id="register-title">This Is a Call to Action</h2>
      <p>The interest form beside this text is added by the website. It sends the program’s name with every sign-up.</p>
      <span data-cms-component="status-badge"></span>
    </div>
    <div data-cms-component="program-form"></div>
  </div>
</section>

<section class="section wrap" aria-labelledby="more-title">
  <h2 id="more-title" class="h3">Other programs</h2>
  <ul class="more" data-cms-component="other-programs"></ul>
</section>
`;
}

