function resources() {
  return `<!--
  THIS IS JUST A TEMPLATE. Every section below is an example: change it, delete it, or replace it
  with your own HTML, classes and Page CSS. Write the article in .article__body; add callouts, images or videos wherever they help.
  Keep the elements marked data-cms-… if you want them to follow Details (title, summary, price, dates…).
  This note is not published.
-->
<article class="article">
  <header class="article__head wrap">
    <nav class="crumbs" aria-label="Breadcrumb"><a href="/resources/">Resources</a><span aria-hidden="true">/</span><span aria-current="page" data-cms-bind="category" data-cms-empty="Article"></span></nav>
    <h1 data-cms-bind="title">This Is the Full HTML Template</h1>
    <p class="article__lead" data-cms-bind="summary">This section demonstrates a heading and introductory paragraph.</p>
    <p class="article__meta" data-cms-component="article-meta"></p>
  </header>
  <div class="article__cover wrap" data-cms-component="featured-image"></div>
  <div class="article__body">
    <p>This is a paragraph. Write the article here: one idea per paragraph, in plain language. The reading time above is calculated from this text.</p>

    <h2>This Is a Card</h2>
    <aside class="callout">
      <p class="callout__label">Example card</p>
      <h3>Highlight one practical point</h3>
      <p>Callout cards draw attention to a tip, a definition or a warning.</p>
    </aside>

    <h2>This Is a List</h2>
    <ul>
      <li>Lists break steps or examples into short lines.</li>
      <li>Keep each item to one idea.</li>
      <li>Use a numbered list when the order matters.</li>
    </ul>

    <h2>This Is an Image</h2>
    <figure class="article__fig fw-media">
      <img src="/assets/images/placeholder-16x9.svg" alt="Placeholder image: replace with an image that supports the article" width="1600" height="900" loading="lazy">
      <figcaption>Replace this placeholder and describe what the image shows.</figcaption>
    </figure>

    <h2>This Is a Video</h2>
    <figure class="fw-video">
      <div class="fw-video__empty">Video placeholder · add a YouTube or Vimeo address in the editor</div>
    </figure>

    <h2>This Is a Testimonial</h2>
    <blockquote class="pull"><p>Example pull quote. Quote people exactly, with their consent, or remove this.</p><cite>Name, role</cite></blockquote>

    <h2>This Is an FAQ</h2>
    <details><summary>Who is this article for?</summary><p>Example answer. Replace or remove.</p></details>
    <details><summary>Where can I learn more?</summary><p>Example answer. Link to a program or another resource.</p></details>

    <aside class="takeaway">
      <h2>Key takeaways</h2>
      <ul class="ticks">
        <li>Summarise the article in two or three points.</li>
        <li>End with one action the reader can take today.</li>
      </ul>
    </aside>

    <aside class="article__cta">
      <h2>This Is a Call to Action</h2>
      <p>The button below uses the destination URL from Details (for downloads and guides). It is hidden when there is none.</p>
      <a class="btn" href="#" data-cms-href="resource-url">Get the resource <span class="btn__arrow" aria-hidden="true">↗</span></a>
    </aside>
  </div>
</article>
<section class="section wrap" aria-labelledby="related-title">
  <h2 id="related-title" class="h3">Keep reading</h2>
  <ul class="more" data-cms-component="related-articles"></ul>
</section>
`;
}

export function starterTemplate(collection) {
  const html = { programs, events, resources }[collection]?.() ?? (collection === "testimonials" ? TESTIMONIAL_CARD + "\n" : "");
  return { html, css: collection === "testimonials" ? "" : CSS };
}

// Blocks the visual editor can insert (Insert menu). Same classes as the starters.
